namespace PdfKnead.EInvoice;

/// <summary>
/// The business rules per profile of ZUGFeRD / Factur-X (stage 4, part e1; KONZEPT.md, „Weg für Stufe 4, Teil e“): an invoice of the
/// profiles MINIMUM, BASIC WL and BASIC is checked by the rules of EN 16931 (and the code lists) its profile lists — the others do not apply
/// to it (a MINIMUM invoice has no lines by design: BR-16 is no finding there). Which rule applies in which profile comes from the
/// specification Factur-X 1.09.2 / ZUGFeRD 2.5.2, sheet „Business Rules“ (Zuordnung/profile.tsv, generated by profile.py; Apache-2.0,
/// docs/PATENTE.md). Only CII, to which the profiles are bound; EN16931 is the whole standard. EXTENDED (part e3) likewise: the rules of
/// the standard it does not list give way to its own (BR-FXEXT, InvoiceRules.Extended.cs).
/// </summary>
public static partial class InvoiceRules
{
    private static readonly Lazy<Dictionary<string, InvoiceProfile[]>> ProfileTable = new(LoadProfileTable);

    private static Dictionary<string, InvoiceProfile[]> LoadProfileTable()
    {
        var table = new Dictionary<string, InvoiceProfile[]>(StringComparer.Ordinal);
        foreach (var line in InvoiceMap.Resource("profile.tsv"))
        {
            if (line.Length == 0 || line[0] == '#') continue;
            var cols = line.Split('\t');
            if (cols.Length != 2) throw new InvalidDataException("profile.tsv: Zeile mit falscher Spaltenzahl");
            table[cols[0]] = [.. cols[1].Split(',', StringSplitOptions.RemoveEmptyEntries).Select(p => p switch
            {
                "MINIMUM" => InvoiceProfile.Minimum,
                "BASICWL" => InvoiceProfile.BasicWl,
                "BASIC" => InvoiceProfile.Basic,
                "EN16931" => InvoiceProfile.En16931,
                "EXTENDED" => InvoiceProfile.Extended,
                _ => throw new InvalidDataException($"profile.tsv: unbekanntes Profil {p}"),
            })];
        }
        return table;
    }

    /// <summary>The profiles whose rules the table narrows (part e1; EXTENDED part e3 — EN16931 is the whole standard).</summary>
    private static bool NarrowedProfile(InvoiceProfile profile) =>
        profile is InvoiceProfile.Minimum or InvoiceProfile.BasicWl or InvoiceProfile.Basic or InvoiceProfile.Extended;

    /// <summary>
    /// Whether a rule applies to the invoice: a rule of EN 16931 or of the code lists in a CII invoice of a narrowed profile only where the
    /// specification lists it for that profile; every other rule as before.
    /// </summary>
    private static bool AppliesInProfile(InvoiceRule rule, Context c) =>
        rule.Source is not (Source or CodeSource) || c.Invoice.Kind.Syntax != InvoiceSyntax.Cii || !NarrowedProfile(c.Invoice.Kind.Profile)
        || !ProfileTable.Value.TryGetValue(rule.Id, out var profiles) || profiles.Contains(c.Invoice.Kind.Profile);

    /// <summary>Whether the invoice is of a narrowed profile that has no lines (BR-16, „an invoice has a line“, does not apply in it: BASIC WL, MINIMUM).</summary>
    private static bool ProfileWithoutLines(Context c) =>
        c.Invoice.Kind.Syntax == InvoiceSyntax.Cii && NarrowedProfile(c.Invoice.Kind.Profile) && !ProfilesOf("BR-16").Contains(c.Invoice.Kind.Profile);

    /// <summary>Every rule the specification lists for a profile (for the tests: is each one checked, or left out for a reason?).</summary>
    internal static IEnumerable<string> RulesListedFor(InvoiceProfile profile) => ProfileTable.Value.Where(p => p.Value.Contains(profile)).Select(p => p.Key);

    /// <summary>The profiles of ZUGFeRD / Factur-X in which the specification lists a rule (empty if it lists it nowhere).</summary>
    public static IReadOnlyList<InvoiceProfile> ProfilesOf(string ruleId) => ProfileTable.Value.TryGetValue(ruleId, out var p) ? p : [];
}
